#![allow(dead_code)]
//! Fixture images shared by the image pipeline tests.
//!
//! `TINY_PNG`, `TINY_JPEG`, `MEDIUM_PNG_100X100`, and `LARGE_PNG_200X200` are
//! the exact fixtures from `packages/coding-agent/test/image-processing.test.ts`.

pub const TINY_PNG: &str = "";

pub const TINY_JPEG: &str = "";

pub const MEDIUM_PNG_100X100: &str = "";

pub const LARGE_PNG_200X200: &str = "";

pub const TINY_PNG_1X1: &str =
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8DwHwAFBQIAX8jx0gAAAABJRU5ErkJggg==";

pub fn decode(value: &str) -> Vec<u8> {
    pi_agent_core::harness::tools::image::decode_base64(value)
}

pub fn encode(bytes: &[u8]) -> String {
    pi_agent_core::harness::tools::image::encode_base64(bytes)
}

/// Encodes an RGBA checkerboard PNG whose pixels are all distinct.
pub fn checker_png(width: u32, height: u32) -> Vec<u8> {
    let mut buffer = Vec::new();
    let pixels = image::RgbaImage::from_fn(width, height, |x, y| {
        image::Rgba([
            (x * 37 % 256) as u8,
            (y * 53 % 256) as u8,
            ((x + y) * 29 % 256) as u8,
            255,
        ])
    });
    image::DynamicImage::ImageRgba8(pixels)
        .write_to(&mut std::io::Cursor::new(&mut buffer), image::ImageOutputFormat::Png)
        .expect("fixture PNG must encode");
    buffer
}

/// Encodes a raw RGBA PNG for the supplied pixel buffer.
pub fn rgba_png(width: u32, height: u32, pixels: &[u8]) -> Vec<u8> {
    let mut buffer = Vec::new();
    let image = image::RgbaImage::from_raw(width, height, pixels.to_vec()).expect("pixel buffer must fit");
    image::DynamicImage::ImageRgba8(image)
        .write_to(&mut std::io::Cursor::new(&mut buffer), image::ImageOutputFormat::Png)
        .expect("fixture PNG must encode");
    buffer
}
